package main

import "fmt"

// Slice operations in Go
func main() {
  arr := []int{10, 20, 30, 40, 50}

  // Access by index — O(1)
  fmt.Println(arr[2])  // 30

  // Search — O(n)
  idx := -1
  for i, v := range arr {
      if v == 40 { idx = i; break }
  }

  // Insert at position — O(n)
  arr = append(arr[:2], append([]int{25}, arr[2:]...)...)

  // Append to end — Amortized O(1)
  arr = append(arr, 60)

  // Delete by value — O(n)
  for i, v := range arr {
      if v == 25 {
          arr = append(arr[:i], arr[i+1:]...)
          break
      }
  }

  fmt.Println(arr)
}
